import requests

response = requests.post(
    "https://api.aimlapi.com/v1/images/generations",
    headers={
        "Authorization": "Bearer <YOUR_AIMLAPI_KEY>",
        "Content-Type": "application/json",
    },
    json={'model': 'klingai/image-v4-image-to-image', 'prompt': 'Describe what you want the model to generate.', 'image_urls': ['https://example.com/input.jpg']},
)

print(response.json())
